shell_commands.command:
cd /testbed && printf '%s\n' '{"foo":[1,2,3]}' | ./jq '.foo.[]'; cd /testbed && printf '%s\n' '{"foo":[1,2,3]}' | ./jq '.foo.[1:2]'; cd /testbed && sed -n '3758,3807p' src/parser.c && sed -n '125,182p' tests/jq.test && sed -n '350,415p' docs/content/manual/manual.yml && python3 - <<'PY'
import json
x=json.load(open('/tmp/jq-peeky-describe.json'))
print('Parser error breakpoint lines:', [l for l in x['breakpoint_lines']['src/parser.c'] if 3760<=l<=3805])
print('Other describe keys:', [k for k in x if k not in ('units','breakpoint_lines')])
f=x.get('functions', [])
if isinstance(f,dict): print(str(f.get('yyparse', f))[:6500])
else:
 for v in f:
  if 'yyparse' in str(v) or 'yyerror' in str(v): print(v)
PY

