+[1,2,3]
+
+[.foo.[1:3], .["foo"].[1:], .foo.[:2]]
+{"foo":[0,1,2,3]}
+[[1,2],[1,2,3],[0,1]]
+
+[.foo.[1:3], .["foo"].[1:], .foo.[:2]]
+{"foo":"abcd"}
+["bc","bcd","ab"]
+
+[.[] | .foo.[1:3]?, .foo.[1:]?, .foo.[:2]?]
+[{"foo":1},{"foo":{}},{"foo":[0,1,2,3]}]
+[[1,2],[1,2,3],[0,1]]
+
+[path(.foo.[]), path(.foo.[1:3]), path(.foo.[1:]), path(.foo.[:2])]
+{"foo":[0,1,2,3]}
+[["foo",0],["foo",1],["foo",2],["foo",3],["foo",{"start":1,"end":3}],["foo",{"start":1,"end":null}],["foo",{"start":null,"end":2}]]
+
+.foo.[] |= . + 1 | .foo.[1:3] = [9]
+{"foo":[0,1,2,3]}
+{"foo":[1,9,4]}
+
 ."foo"."bar"
 {"foo": {"bar": 20}}
 20
